import { useEffect, useMemo, useState } from 'react'
import { TeamAvatar } from './TeamAvatar'
import { standingsMobileTeamName } from './teamNameUtils.js'
import { fetchLeagueDataJson } from './leagueDataFetch.js'
import './WeeklyRecap.css'

/**
 * Weekly recap — matchup-centric. After each finished gameweek: an
 * odds-vs-reality strip (how the model's pre-match calls aged), the week's
 * superlatives, then one card per fixture with the score, the pre-match
 * call, a template recap paragraph and both teams' table context. All
 * generated by scripts/build-weekly-recaps.mjs; GW selector keeps every past
 * week readable.
 */
export function WeeklyRecap({ teamLogoMap = {}, kitIndexByEntry }) {
  const [data, setData] = useState(null)
  const [failed, setFailed] = useState(false)
  const [selectedGw, setSelectedGw] = useState(null)

  useEffect(() => {
    let alive = true
    fetchLeagueDataJson('weekly-recaps.json')
      .then((json) => {
        if (alive) setData(json)
      })
      .catch(() => {
        if (alive) setFailed(true)
      })
    return () => {
      alive = false
    }
  }, [])

  const gameweeks = useMemo(() => data?.gameweeks ?? [], [data])
  const activeGw = useMemo(() => {
    if (gameweeks.length === 0) return null
    const wanted = selectedGw ?? gameweeks[gameweeks.length - 1].gw
    return gameweeks.find((g) => g.gw === wanted) ?? gameweeks[gameweeks.length - 1]
  }, [gameweeks, selectedGw])

  if (failed) {
    return (
      <section className="tile tile--compact" aria-label="Weekly recap">
        <h2 className="tile-title tile-title--sm">Weekly recap</h2>
        <p className="weekly-recap__note">Recaps unavailable right now.</p>
      </section>
    )
  }
  if (!data) {
    return (
      <section className="tile tile--compact" aria-label="Weekly recap">
        <h2 className="tile-title tile-title--sm">Weekly recap</h2>
        <p className="weekly-recap__note">Loading…</p>
      </section>
    )
  }

  if (gameweeks.length === 0) {
    return (
      <section className="tile tile--compact weekly-recap" aria-label="Weekly recap">
        <h2 className="tile-title tile-title--sm">Weekly recap</h2>
        <p className="weekly-recap__empty">
          The first recap drops when GW1 finishes — every matchup gets the score,
          what the model called pre-match, and where it leaves both sides.
        </p>
        <p className="weekly-recap__note">
          Until then, the Predictions tab has the model's pre-season view.
        </p>
      </section>
    )
  }

  const decided = activeGw.model.hits + activeGw.model.misses

  return (
    <>
      <section
        className="tile tile--compact weekly-recap"
        aria-labelledby="weekly-recap-heading"
      >
        <div className="tile-head-row tile-head-row--tight weekly-recap__head">
          <h2 id="weekly-recap-heading" className="tile-title tile-title--sm">
            GW{activeGw.gw} recap
          </h2>
          {gameweeks.length > 1 ? (
            <label className="weekly-recap__select-wrap">
              <span className="visually-hidden">Choose gameweek</span>
              <select
                className="weekly-recap__select"
                value={activeGw.gw}
                onChange={(e) => setSelectedGw(Number(e.target.value))}
              >
                {[...gameweeks].reverse().map((g) => (
                  <option key={g.gw} value={g.gw}>
                    GW{g.gw}
                  </option>
                ))}
              </select>
            </label>
          ) : null}
        </div>

        <div className="weekly-recap__superlatives">
          {activeGw.superlatives.weekHigh ? (
            <span className="weekly-recap__superlative">
              <span className="weekly-recap__superlative-label">Week high</span>
              <span className="weekly-recap__superlative-value">
                {standingsMobileTeamName(activeGw.superlatives.weekHigh.name)} ·{' '}
                <span className="tabular">{activeGw.superlatives.weekHigh.points}</span>
              </span>
            </span>
          ) : null}
          {activeGw.superlatives.closest ? (
            <span className="weekly-recap__superlative">
              <span className="weekly-recap__superlative-label">Closest</span>
              <span className="weekly-recap__superlative-value">
                {standingsMobileTeamName(activeGw.superlatives.closest.homeName)} v{' '}
                {standingsMobileTeamName(activeGw.superlatives.closest.awayName)} (
                <span className="tabular">±{activeGw.superlatives.closest.margin}</span>)
              </span>
            </span>
          ) : null}
          {activeGw.superlatives.starPlayer ? (
            <span className="weekly-recap__superlative">
              <span className="weekly-recap__superlative-label">Star player</span>
              <span className="weekly-recap__superlative-value">
                {activeGw.superlatives.starPlayer.name} ·{' '}
                <span className="tabular">{activeGw.superlatives.starPlayer.pts}</span> (
                {standingsMobileTeamName(activeGw.superlatives.starPlayer.teamName)})
              </span>
            </span>
          ) : null}
        </div>

        {decided > 0 || activeGw.model.draws > 0 ? (
          <div className="weekly-recap__odds" role="status">
            <div className="weekly-recap__odds-line">
              <span className="weekly-recap__odds-label">Odds accuracy</span>
              <span className="weekly-recap__odds-value tabular">
                {activeGw.model.hits} of {decided}
              </span>
              {activeGw.model.calls.length > 0 ? (
                <span className="weekly-recap__odds-dots" aria-hidden>
                  {activeGw.model.calls.map((c, i) => (
                    <span
                      key={i}
                      className={
                        'weekly-recap__odds-dot' +
                        (c.outcome === 'hit'
                          ? ' weekly-recap__odds-dot--hit'
                          : c.outcome === 'miss'
                            ? ' weekly-recap__odds-dot--miss'
                            : ' weekly-recap__odds-dot--draw')
                      }
                      title={`${standingsMobileTeamName(c.favoriteName)} ${c.favoritePct}% — ${
                        c.outcome === 'hit'
                          ? 'called it'
                          : c.outcome === 'miss'
                            ? 'wrong'
                            : 'drawn'
                      }`}
                    />
                  ))}
                </span>
              ) : null}
              <span className="weekly-recap__odds-note">
                winner calls landed
                {activeGw.model.draws ? ` (${activeGw.model.draws} drawn)` : ''}
                {activeGw.model.avgAbsErr != null
                  ? ` · avg miss ±${activeGw.model.avgAbsErr}`
                  : ''}
              </span>
            </div>
            {activeGw.model.upset ? (
              <p className="weekly-recap__upset">
                Upset of the week:{' '}
                {standingsMobileTeamName(activeGw.model.upset.winnerName)} beat{' '}
                {standingsMobileTeamName(activeGw.model.upset.loserName)} with just a{' '}
                <span className="tabular">{activeGw.model.upset.winnerPct}%</span>{' '}
                pre-match chance.
              </p>
            ) : null}
          </div>
        ) : null}
      </section>

      {activeGw.matchups.map((m) => (
        <MatchupCard
          key={`${m.home.entryId}-${m.away.entryId}`}
          matchup={m}
          teamLogoMap={teamLogoMap}
          kitIndexByEntry={kitIndexByEntry}
        />
      ))}
    </>
  )
}

function MatchupCard({ matchup: m, teamLogoMap, kitIndexByEntry }) {
  const homeWon = m.winner === m.home.entryId
  const awayWon = m.winner === m.away.entryId
  return (
    <section
      className="tile tile--compact weekly-recap-matchup"
      aria-label={`${m.home.name} v ${m.away.name}`}
    >
      <div className="weekly-recap-matchup__scoreline">
        <span
          className={
            'weekly-recap-matchup__side weekly-recap-matchup__side--home' +
            (homeWon ? ' weekly-recap-matchup__side--won' : '')
          }
        >
          <span className="weekly-recap-matchup__side-label">
            <span className="weekly-recap-matchup__side-name">{m.home.name}</span>
            {m.home.manager ? (
              <span className="weekly-recap-matchup__side-mgr">{m.home.manager}</span>
            ) : null}
          </span>
          <TeamAvatar
            entryId={m.home.entryId}
            name={m.home.name}
            size="md"
            logoMap={teamLogoMap}
            kitIndexByEntry={kitIndexByEntry}
          />
        </span>
        <span className="weekly-recap-matchup__score tabular">
          {m.home.points}–{m.away.points}
        </span>
        <span
          className={
            'weekly-recap-matchup__side' +
            (awayWon ? ' weekly-recap-matchup__side--won' : '')
          }
        >
          <TeamAvatar
            entryId={m.away.entryId}
            name={m.away.name}
            size="md"
            logoMap={teamLogoMap}
            kitIndexByEntry={kitIndexByEntry}
          />
          <span className="weekly-recap-matchup__side-label">
            <span className="weekly-recap-matchup__side-name">{m.away.name}</span>
            {m.away.manager ? (
              <span className="weekly-recap-matchup__side-mgr">{m.away.manager}</span>
            ) : null}
          </span>
        </span>
      </div>

      {m.odds ? (
        <p className="weekly-recap-matchup__precall">
          Pre-match:{' '}
          {standingsMobileTeamName(
            m.odds.favoriteSide === 'home' ? m.home.name : m.away.name,
          )}{' '}
          <span className="tabular">{Math.round(m.odds.favoritePct)}%</span>
          {m.predicted ? (
            <>
              {' '}
              · points call{' '}
              <span className="tabular">
                {Math.round(m.predicted.home)}–{Math.round(m.predicted.away)}
              </span>
            </>
          ) : null}
          <span
            className={
              'weekly-recap-matchup__outcome-dot' +
              (m.odds.outcome === 'hit'
                ? ' weekly-recap-matchup__outcome-dot--hit'
                : m.odds.outcome === 'miss'
                  ? ' weekly-recap-matchup__outcome-dot--miss'
                  : ' weekly-recap-matchup__outcome-dot--draw')
            }
            title={
              m.odds.outcome === 'hit'
                ? 'Model called it'
                : m.odds.outcome === 'miss'
                  ? 'Model missed'
                  : 'Drawn'
            }
            aria-hidden
          />
          <span className="visually-hidden">
            {m.odds.outcome === 'hit'
              ? 'Model called it'
              : m.odds.outcome === 'miss'
                ? 'Model missed'
                : 'Drawn'}
          </span>
        </p>
      ) : null}

      <p className="weekly-recap-matchup__prose">{m.sentences.join(' ')}</p>

      <div className="weekly-recap-matchup__teams">
        {[m.home, m.away].map((t) => (
          <div key={t.entryId} className="weekly-recap-matchup__team-row">
            <TeamAvatar
              entryId={t.entryId}
              name={t.name}
              size="sm"
              logoMap={teamLogoMap}
              kitIndexByEntry={kitIndexByEntry}
            />
            <span className="weekly-recap-matchup__team-id">
              <span className="weekly-recap-matchup__team-name">
                {standingsMobileTeamName(t.name)}
              </span>
              {t.manager ? (
                <span className="weekly-recap-matchup__team-mgr">{t.manager}</span>
              ) : null}
            </span>
            <span className="weekly-recap-matchup__team-rank tabular">
              {ordinal(t.rank)}
              {t.prevRank != null && t.prevRank !== t.rank ? (
                <span
                  className={
                    'weekly-recap-matchup__rank-move ' +
                    (t.rank < t.prevRank
                      ? 'weekly-recap-matchup__rank-move--up'
                      : 'weekly-recap-matchup__rank-move--down')
                  }
                  aria-label={
                    t.rank < t.prevRank
                      ? `up from ${ordinal(t.prevRank)}`
                      : `down from ${ordinal(t.prevRank)}`
                  }
                >
                  {t.rank < t.prevRank ? '▲' : '▼'}
                </span>
              ) : null}
            </span>
            <span className="weekly-recap-matchup__team-record tabular">
              {t.record.w}-{t.record.d}-{t.record.l}
            </span>
            {t.players?.top ? (
              <span
                className="weekly-recap-matchup__team-top"
                title={`Top scorer: ${t.players.top.name} (${t.players.top.pts})`}
              >
                ★ {t.players.top.name}{' '}
                <span className="tabular">{t.players.top.pts}</span>
              </span>
            ) : null}
            {t.streak && t.streak.len >= 2 ? (
              <span
                className={
                  'weekly-recap-matchup__streak' +
                  (t.streak.type === 'W'
                    ? ' weekly-recap-matchup__streak--w'
                    : t.streak.type === 'L'
                      ? ' weekly-recap-matchup__streak--l'
                      : '')
                }
                title={`${t.streak.len} ${t.streak.type === 'W' ? 'wins' : t.streak.type === 'L' ? 'defeats' : 'draws'} in a row`}
              >
                {t.streak.type}
                {t.streak.len}
              </span>
            ) : null}
            {t.titleOdds ? (
              <span className="weekly-recap-matchup__team-odds tabular">
                title {t.titleOdds.before}% → {t.titleOdds.after}%
              </span>
            ) : null}
          </div>
        ))}
      </div>
    </section>
  )
}

function ordinal(n) {
  const s = ['th', 'st', 'nd', 'rd']
  const v = n % 100
  return `${n}${s[(v - 20) % 10] || s[v] || s[0]}`
}
